1	<!DOCTYPE html>
2	<html lang="zh-CN">
3	<head>
4	    <meta charset="UTF-8">
5	    <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=no">
6	    <title>跳一跳 - Jump Jump</title>
7	    <style>
8	        * {
9	            margin: 0;
10	            padding: 0;
11	            box-sizing: border-box;
12	            -webkit-tap-highlight-color: transparent;
13	        }
14	        body {
15	            background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
16	            min-height: 100vh;
17	            display: flex;
18	            justify-content: center;
19	            align-items: center;
20	            font-family: 'Segoe UI', system-ui, sans-serif;
21	            overflow: hidden;
22	        }
23	        #gameContainer {
24	            position: relative;
25	            touch-action: none;
26	        }
27	        canvas {
28	            display: block;
29	            border-radius: 16px;
30	            box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5), 0 0 100px rgba(79, 172, 254, 0.1);
31	        }
32	        #ui {
33	            position: absolute;
34	            top: 0;
35	            left: 0;
36	            width: 100%;
37	            height: 100%;
38	            pointer-events: none;
39	            display: flex;
40	            flex-direction: column;
41	            align-items: center;
42	        }
43	        #scoreDisplay {
44	            margin-top: 30px;
45	            font-size: 64px;
46	            font-weight: 800;
47	            color: #fff;
48	            text-shadow: 0 4px 20px rgba(79, 172, 254, 0.5);
49	            letter-spacing: -2px;
50	            transition: transform 0.15s ease;
51	        }
52	        #scoreDisplay.bump {
53	            transform: scale(1.2);
54	        }
55	        #bestScore {
56	            font-size: 16px;
57	            color: rgba(255, 255, 255, 0.5);
58	            margin-top: 4px;
59	        }
60	        #gameOver {
61	            position: absolute;
62	            top: 50%;
63	            left: 50%;
64	            transform: translate(-50%, -50%) scale(0.8);
65	            background: rgba(15, 25, 45, 0.95);
66	            backdrop-filter: blur(20px);
67	            border-radius: 24px;
68	            padding: 40px 50px;
69	            text-align: center;
70	            opacity: 0;
71	            pointer-events: none;
72	            transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
73	            border: 1px solid rgba(79, 172, 254, 0.2);
74	            box-shadow: 0 30px 80px rgba(0, 0, 0, 0.6);
75	        }
76	        #gameOver.show {
77	            opacity: 1;
78	            transform: translate(-50%, -50%) scale(1);
79	            pointer-events: auto;
80	        }
81	        #gameOver h2 {
82	            color: #fff;
83	            font-size: 28px;
84	            margin-bottom: 8px;
85	            font-weight: 700;
86	        }
87	        #gameOver .final-score {
88	            color: #4facfe;
89	            font-size: 56px;
90	            font-weight: 800;
91	            margin: 10px 0;
92	            text-shadow: 0 0 30px rgba(79, 172, 254, 0.6);
93	        }
94	        #gameOver .best-label {
95	            color: rgba(255, 255, 255, 0.4);
96	            font-size: 14px;
97	            margin-bottom: 24px;
98	        }
99	        #restartBtn {
100	            background: linear-gradient(135deg, #4facfe 0%, #00f2fe 100%);
101	            color: #1a1a2e;
102	            border: none;
103	            padding: 14px 48px;
104	            font-size: 18px;
105	            font-weight: 700;
106	            border-radius: 50px;
107	            cursor: pointer;
108	            pointer-events: auto;
109	            transition: all 0.2s ease;
110	            box-shadow: 0 8px 30px rgba(79, 172, 254, 0.4);
111	            letter-spacing: 1px;
112	        }
113	        #restartBtn:hover {
114	            transform: translateY(-2px);
115	            box-shadow: 0 12px 40px rgba(79, 172, 254, 0.6);
116	        }
117	        #restartBtn:active {
118	            transform: translateY(0);
119	        }
120	        #hint {
121	            position: absolute;
122	            bottom: 30px;
123	            left: 50%;
124	            transform: translateX(-50%);
125	            color: rgba(255, 255, 255, 0.3);
126	            font-size: 13px;
127	            transition: opacity 0.5s ease;
128	        }
129	        #hint.hide {
130	            opacity: 0;
131	        }
132	        #powerBar {
133	            position: absolute;
134	            bottom: 60px;
135	            left: 50%;
136	            transform: translateX(-50%);
137	            width: 120px;
138	            height: 8px;
139	            background: rgba(255, 255, 255, 0.1);
140	            border-radius: 4px;
141	            overflow: hidden;
142	            opacity: 0;
143	            transition: opacity 0.2s ease;
144	        }
145	        #powerBar.show {
146	            opacity: 1;
147	        }
148	        #powerFill {
149	            height: 100%;
150	            width: 0%;
151	            background: linear-gradient(90deg, #4facfe, #00f2fe);
152	            border-radius: 4px;
153	            transition: width 0.05s linear;
154	        }
155	    </style>
156	</head>
157	<body>
158	    <div id="gameContainer">
159	        <canvas id="gameCanvas"></canvas>
160	        <div id="ui">
161	            <div id="scoreDisplay">0</div>
162	            <div id="bestScore">最高: 0</div>
163	            <div id="powerBar"><div id="powerFill"></div></div>
164	            <div id="hint">按住屏幕蓄力，松开跳跃</div>
165	        </div>
166	        <div id="gameOver">
167	            <h2>游戏结束</h2>
168	            <div class="final-score" id="finalScore">0</div>
169	            <div class="best-label" id="finalBest">最高: 0</div>
170	            <button id="restartBtn">再来一局</button>
171	        </div>
172	    </div>
173	
174	    <script>
175	    (function() {
176	        const canvas = document.getElementById('gameCanvas');
177	        const ctx = canvas.getContext('2d');
178	        const scoreDisplay = document.getElementById('scoreDisplay');
179	        const bestScoreDisplay = document.getElementById('bestScore');
180	        const gameOverPanel = document.getElementById('gameOver');
181	        const finalScoreEl = document.getElementById('finalScore');
182	        const finalBestEl = document.getElementById('finalBest');
183	        const restartBtn = document.getElementById('restartBtn');
184	        const hintEl = document.getElementById('hint');
185	        const powerBar = document.getElementById('powerBar');
186	        const powerFill = document.getElementById('powerFill');
187	        const container = document.getElementById('gameContainer');
188	
189	        // Responsive sizing
190	        const BASE_WIDTH = 400;
191	        const BASE_HEIGHT = 650;
192	        let scale = 1;
193	
194	        function resize() {
195	            const maxW = window.innerWidth - 32;
196	            const maxH = window.innerHeight - 32;
197	            scale = Math.min(maxW / BASE_WIDTH, maxH / BASE_HEIGHT, 1.5);
198	            canvas.width = BASE_WIDTH * scale;
199	            canvas.height = BASE_HEIGHT * scale;
200	            canvas.style.width = canvas.width + 'px';
201	            canvas.style.height = canvas.height + 'px';
202	            ctx.setTransform(scale, 0, 0, scale, 0, 0);
203	        }
204	        resize();
205	        window.addEventListener('resize', resize);
206	
207	        // Game state
208	        let state = 'idle'; // idle, charging, jumping, falling, dead
209	        let score = 0;
210	        let bestScore = parseInt(localStorage.getItem('jumpBest') || '0');
211	        bestScoreDisplay.textContent = '最高: ' + bestScore;
212	
213	        // Player
214	        const player = {
215	            x: BASE_WIDTH / 2,
216	            y: 0,
217	            vx: 0,
218	            vy: 0,
219	            size: 22,
220	            color: '#4facfe',
221	            glowColor: 'rgba(79, 172, 254, 0.6)',
222	            trail: [],
223	            onGround: false
224	        };
225	
226	        // Platforms
227	        let platforms = [];
228	        const PLATFORM_MIN_W = 50;
229	        const PLATFORM_MAX_W = 110;
230	        const PLATFORM_H = 14;
231	        const PLATFORM_GAP_MIN = 80;
232	        const PLATFORM_GAP_MAX = 180;
233	
234	        // Camera
235	        let cameraY = 0;
236	        let cameraTargetY = 0;
237	
238	        // Charge mechanic
239	        let chargeStart = 0;
240	        let chargePower = 0;
241	        const MAX_CHARGE = 1.5; // seconds
242	        const JUMP_POWER = 14;
243	        const GRAVITY = 0.55;
244	
245	        // Particles
246	        let particles = [];
247	
248	        // Background stars
249	        let stars = [];
250	        for (let i = 0; i < 60; i++) {
251	            stars.push({
252	                x: Math.random() * BASE_WIDTH,
253	                y: Math.random() * BASE_HEIGHT * 3,
254	                size: Math.random() * 1.5 + 0.5,
255	                alpha: Math.random() * 0.5 + 0.1,
256	                speed: Math.random() * 0.3 + 0.1
257	            });
258	        }
259	
260	        function initGame() {
261	            state = 'idle';
262	            score = 0;
263	            scoreDisplay.textContent = '0';
264	            scoreDisplay.classList.remove('bump');
265	            gameOverPanel.classList.remove('show');
266	            hintEl.classList.remove('hide');
267	            powerBar.classList.remove('show');
268	
269	            cameraY = 0;
270	            cameraTargetY = 0;
271	            player.trail = [];
272	            particles = [];
273	
274	            player.x = BASE_WIDTH / 2;
275	            player.y = BASE_HEIGHT - 120;
276	            player.vx = 0;
277	            player.vy = 0;
278	            player.onGround = true;
279	
280	            platforms = [];
281	            // Starting platform
282	            platforms.push({
283	                x: BASE_WIDTH / 2 - 60,
284	                y: BASE_HEIGHT - 80,
285	                w: 120,
286	                h: PLATFORM_H,
287	                color: '#4facfe',
288	                glowColor: 'rgba(79, 172, 254, 0.3)'
289	            });
290	
291	            // Generate initial platforms
292	            let lastX = BASE_WIDTH / 2;
293	            let lastY = BASE_HEIGHT - 80;
294	            for (let i = 0; i < 8; i++) {
295	                const gap = PLATFORM_GAP_MIN + Math.random() * (PLATFORM_GAP_MAX - PLATFORM_GAP_MIN);
296	                const dy = 50 + Math.random() * 80;
297	                const dx = (Math.random() - 0.5) * 200;
298	                const w = PLATFORM_MIN_W + Math.random() * (PLATFORM_MAX_W - PLATFORM_MIN_W);
299	                lastX = Math.max(w / 2, Math.min(BASE_WIDTH - w / 2, lastX + dx));
300	                lastY -= dy;
301	                const hue = 180 + Math.random() * 40;
302	                platforms.push({
303	                    x: lastX - w / 2,
304	                    y: lastY,
305	                    w: w,
306	                    h: PLATFORM_H,
307	                    color: `hsl(${hue}, 80%, 60%)`,
308	                    glowColor: `hsla(${hue}, 80%, 60%, 0.3)`
309	                });
310	            }
311	        }
312	
313	        function generatePlatform() {
314	            const last = platforms[platforms.length - 1];
315	            const gap = PLATFORM_GAP_MIN + Math.random() * (PLATFORM_GAP_MAX - PLATFORM_GAP_MIN);
316	            const dy = 50 + Math.random() * 80;
317	            const dx = (Math.random() - 0.5) * 220;
318	            const w = PLATFORM_MIN_W + Math.random() * (PLATFORM_MAX_W - PLATFORM_MIN_W);
319	            let newX = last.x + last.w / 2 + dx;
320	            newX = Math.max(w / 2, Math.min(BASE_WIDTH - w / 2, newX));
321	            const hue = 180 + Math.random() * 40;
322	            platforms.push({
323	                x: newX - w / 2,
324	                y: last.y - dy,
325	                w: w,
326	                h: PLATFORM_H,
327	                color: `hsl(${hue}, 80%, 60%)`,
328	                glowColor: `hsla(${hue}, 80%, 60%, 0.3)`
329	            });
330	        }
331	
332	        function spawnParticles(x, y, color, count, spread) {
333	            for (let i = 0; i < count; i++) {
334	                const angle = Math.random() * Math.PI * 2;
335	                const speed = Math.random() * spread + 1;
336	                particles.push({
337	                    x: x,
338	                    y: y,
339	                    vx: Math.cos(angle) * speed,
340	                    vy: Math.sin(angle) * speed - 2,
341	                    life: 1,
342	                    decay: 0.02 + Math.random() * 0.02,
343	                    size: Math.random() * 4 + 2,
344	                    color: color
345	                });
346	            }
347	        }
348	
349	        function addScore() {
350	            score++;
351	            scoreDisplay.textContent = score;
352	            scoreDisplay.classList.add('bump');
353	            setTimeout(() => scoreDisplay.classList.remove('bump'), 150);
354	            if (score > bestScore) {
355	                bestScore = score;
356	                localStorage.setItem('jumpBest', bestScore);
357	                bestScoreDisplay.textContent = '最高: ' + bestScore;
358	            }
359	            spawnParticles(player.x, player.y + player.size, player.color, 15, 4);
360	        }
361	
362	        function gameOver() {
363	            state = 'dead';
364	            spawnParticles(player.x, player.y, '#ff6b6b', 30, 6);
365	            finalScoreEl.textContent = score;
366	            finalBestEl.textContent = '最高: ' + bestScore;
367	            setTimeout(() => {
368	                gameOverPanel.classList.add('show');
369	            }, 600);
370	        }
371	
372	        function update(dt) {
373	            if (state === 'charging') {
374	                const elapsed = (Date.now() - chargeStart) / 1000;
375	                chargePower = Math.min(elapsed / MAX_CHARGE, 1);
376	                powerFill.style.width = (chargePower * 100) + '%';
377	            }
378	
379	            if (state === 'jumping' || state === 'falling') {
380	                // Apply gravity
381	                player.vy += GRAVITY;
382	                player.x += player.vx;
383	                player.y += player.vy;
384	
385	                // Trail
386	                player.trail.unshift({ x: player.x, y: player.y, alpha: 1 });
387	                if (player.trail.length > 12) player.trail.pop();
388	                player.trail.forEach(t => t.alpha *= 0.85);
389	
390	                // Camera follow
391	                const targetCamY = player.y - BASE_HEIGHT * 0.4;
392	                cameraTargetY = Math.min(cameraTargetY, targetCamY);
393	                cameraY += (cameraTargetY - cameraY) * 0.08;
394	
395	                // Horizontal wrap
396	                if (player.x < -player.size) player.x = BASE_WIDTH + player.size;
397	                if (player.x > BASE_WIDTH + player.size) player.x = -player.size;
398	
399	                // Check platform collision
400	                if (player.vy > 0) {
401	                    for (let plat of platforms) {
402	                        if (player.x + player.size * 0.6 > plat.x &&
403	                            player.x - player.size * 0.6 < plat.x + plat.w &&
404	                            player.y + player.size >= plat.y &&
405	                            player.y + player.size <= plat.y + plat.h + player.vy + 4) {
406	                            player.y = plat.y - player.size;
407	                            player.vy = 0;
408	                            player.vx = 0;
409	                            state = 'idle';
410	                            player.onGround = true;
411	                            addScore();
412	                            break;
413	                        }
414	                    }
415	                }
416	
417	                // Death check - fell off screen
418	                if (player.y > cameraY + BASE_HEIGHT + 100) {
419	                    gameOver();
420	                }
421	
422	                // Fell below all platforms
423	                if (state !== 'idle' && player.y > cameraY + BASE_HEIGHT + 50) {
424	                    gameOver();
425	                }
426	            }
427	
428	            // Particles
429	            particles = particles.filter(p => {
430	                p.x += p.vx;
431	                p.y += p.vy;
432	                p.vy += 0.15;
433	                p.life -= p.decay;
434	                return p.life > 0;
435	            });
436	
437	            // Generate new platforms as needed
438	            while (platforms.length > 0 && platforms[platforms.length - 1].y > cameraY - 200) {
439	                generatePlatform();
440	            }
441	
442	            // Remove old platforms
443	            platforms = platforms.filter(p => p.y < cameraY + BASE_HEIGHT + 200);
444	        }
445	
446	        function drawBackground() {
447	            // Deep space gradient
448	            const grad = ctx.createLinearGradient(0, 0, 0, BASE_HEIGHT);
449	            grad.addColorStop(0, '#0a0a1a');
450	            grad.addColorStop(1, '#1a1a3a');
451	            ctx.fillStyle = grad;
452	            ctx.fillRect(0, 0, BASE_WIDTH, BASE_HEIGHT);
453	
454	            // Stars
455	            stars.forEach(star => {
456	                const sy = ((star.y - cameraY * star.speed) % (BASE_HEIGHT * 3) + BASE_HEIGHT * 3) % (BASE_HEIGHT * 3);
457	                ctx.beginPath();
458	                ctx.arc(star.x, sy, star.size, 0, Math.PI * 2);
459	                ctx.fillStyle = `rgba(255, 255, 255, ${star.alpha})`;
460	                ctx.fill();
461	            });
462	        }
463	
464	        function drawPlatform(plat) {
465	            const sy = plat.y - cameraY;
466	
467	            // Glow
468	            ctx.shadowColor = plat.glowColor;
469	            ctx.shadowBlur = 20;
470	
471	            // Platform body
472	            ctx.beginPath();
473	            ctx.roundRect(plat.x, sy, plat.w, plat.h, 7);
474	            ctx.fillStyle = plat.color;
475	            ctx.fill();
476	
477	            // Top highlight
478	            ctx.beginPath();
479	            ctx.roundRect(plat.x + 3, sy + 2, plat.w - 6, 4, 2);
480	            ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
481	            ctx.fill();
482	
483	            ctx.shadowBlur = 0;
484	        }
485	
486	        function drawPlayer() {
487	            // Trail
488	            player.trail.forEach((t, i) => {
489	                const ty = t.y - cameraY;
490	                const alpha = t.alpha * 0.4;
491	                const size = player.size * (1 - i / player.trail.length) * 0.7;
492	                ctx.beginPath();
493	                ctx.arc(t.x, ty, size, 0, Math.PI * 2);
494	                ctx.fillStyle = `rgba(79, 172, 254, ${alpha})`;
495	                ctx.fill();
496	            });
497	
498	            const py = player.y - cameraY;
499	
500	            // Glow
501	            ctx.shadowColor = player.glowColor;
502	            ctx.shadowBlur = 25;
503	
504	            // Ball
505	            ctx.beginPath();
506	            ctx.arc(player.x, py, player.size, 0, Math.PI * 2);
507	            const ballGrad = ctx.createRadialGradient(
508	                player.x - player.size * 0.3, py - player.size * 0.3, 0,
509	                player.x, py, player.size
510	            );
511	            ballGrad.addColorStop(0, '#a8e6ff');
512	            ballGrad.addColorStop(0.5, '#4facfe');
513	            ballGrad.addColorStop(1, '#0070c0');
514	            ctx.fillStyle = ballGrad;
515	            ctx.fill();
516	
517	            // Shine
518	            ctx.beginPath();
519	            ctx.arc(player.x - player.size * 0.3, py - player.size * 0.3, player.size * 0.25, 0, Math.PI * 2);
520	            ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
521	            ctx.fill();
522	
523	            ctx.shadowBlur = 0;
524	        }
525	
526	        function drawParticles() {
527	            particles.forEach(p => {
528	                const py = p.y - cameraY;
529	                ctx.beginPath();
530	                ctx.arc(p.x, py, p.size * p.life, 0, Math.PI * 2);
531	                ctx.fillStyle = p.color;
532	                ctx.globalAlpha = p.life;
533	                ctx.fill();
534	                ctx.globalAlpha = 1;
535	            });
536	        }
537	
538	        function drawArrow() {
539	            if (state !== 'charging') return;
540	            const py = player.y - cameraY;
541	            const power = chargePower;
542	
543	            // Arrow from player
544	            const arrowLen = 30 + power * 60;
545	            const angle = -Math.PI / 2 - power * Math.PI * 0.3;
546	
547	            ctx.save();
548	            ctx.translate(player.x, py);
549	            ctx.rotate(angle);
550	
551	            // Arrow body
552	            ctx.beginPath();
553	            ctx.moveTo(0, 0);
554	            ctx.lineTo(arrowLen, 0);
555	            ctx.strokeStyle = `rgba(79, 172, 254, ${0.4 + power * 0.6})`;
556	            ctx.lineWidth = 3;
557	            ctx.lineCap = 'round';
558	            ctx.stroke();
559	
560	            // Arrow head
561	            ctx.beginPath();
562	            ctx.moveTo(arrowLen, 0);
563	            ctx.lineTo(arrowLen - 10, -6);
564	            ctx.lineTo(arrowLen - 10, 6);
565	            ctx.closePath();
566	            ctx.fillStyle = `rgba(79, 172, 254, ${0.6 + power * 0.4})`;
567	            ctx.fill();
568	
569	            ctx.restore();
570	        }
571	
572	        function draw() {
573	            ctx.clearRect(0, 0, BASE_WIDTH, BASE_HEIGHT);
574	            drawBackground();
575	
576	            // Draw platforms
577	            platforms.forEach(p => drawPlatform(p));
578	
579	            // Draw particles
580	            drawParticles();
581	
582	            // Draw player
583	            drawPlayer();
584	
585	            // Draw jump arrow
586	            drawArrow();
587	        }
588	
589	        // Game loop
590	        let lastTime = 0;
591	        function loop(timestamp) {
592	            const dt = Math.min((timestamp - lastTime) / 1000, 0.05);
593	            lastTime = timestamp;
594	
595	            update(dt);
596	            draw();
597	
598	            requestAnimationFrame(loop);
599	        }
600	
601	        // Input handling
602	        function startCharge(e) {
603	            e.preventDefault();
604	            if (state !== 'idle') return;
605	            state = 'charging';
606	            chargeStart = Date.now();
607	            chargePower = 0;
608	            powerBar.classList.add('show');
609	            hintEl.classList.add('hide');
610	        }
611	
612	        function releaseJump(e) {
613	            e.preventDefault();
614	            if (state !== 'charging') return;
615	            powerBar.classList.remove('show');
616	
617	            const power = 0.3 + chargePower * 0.7;
618	            const angle = -Math.PI / 2 - chargePower * Math.PI * 0.3;
619	            const speed = JUMP_POWER * power;
620	
621	            player.vx = Math.cos(angle) * speed * 0.5;
622	            player.vy = Math.sin(angle) * speed;
623	            player.onGround = false;
624	            state = 'jumping';
625	            chargePower = 0;
626	            spawnParticles(player.x, player.y + player.size, player.color, 8, 2);
627	        }
628	
629	        // Mouse events
630	        canvas.addEventListener('mousedown', startCharge);
631	        canvas.addEventListener('mouseup', releaseJump);
632	        canvas.addEventListener('mouseleave', (e) => {
633	            if (state === 'charging') releaseJump(e);
634	        });
635	
636	        // Touch events
637	        canvas.addEventListener('touchstart', startCharge, { passive: false });
638	        canvas.addEventListener('touchend', releaseJump, { passive: false });
639	        canvas.addEventListener('touchcancel', (e) => {
640	            if (state === 'charging') releaseJump(e);
641	        });
642	
643	        // Restart button
644	        restartBtn.addEventListener('click', initGame);
